<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const groups=ref<any[]>([]),show=ref(false),form=ref({code:'',module:'',description:''});async function load(){groups.value=(await api.get('/permissions')).data.groups||[]}async function create(){await api.post('/permissions',form.value);show.value=false;await load()}onMounted(load)</script>
<template><div class="page"><div class="page-title"><div><h1>权限管理</h1><p>按模块维护后端授权码，角色通过权限集合获得操作边界</p></div><button class="primary-button" @click="show=true">＋ 新增权限</button></div><section v-for="group in groups" :key="group.Module" class="card"><div class="card-title"><h3>{{group.Module}}</h3><span>{{group.Permissions.length}} 项权限</span></div><table class="data-table"><thead><tr><th>权限编码</th><th>模块</th><th>说明</th></tr></thead><tbody><tr v-for="x in group.Permissions" :key="x.ID"><td><code>{{x.Code}}</code></td><td>{{x.Module}}</td><td>{{x.Description}}</td></tr></tbody></table></section><div v-if="show" class="modal-mask" @click.self="show=false"><div class="modal"><div class="modal-header"><h3>新增权限</h3><button class="close-button" @click="show=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>权限编码</span><input v-model="form.code"></label><label><span>模块</span><input v-model="form.module"></label><label class="full"><span>说明</span><input v-model="form.description"></label></div></div><div class="modal-footer"><button class="secondary-button" @click="show=false">取消</button><button class="primary-button" @click="create">创建</button></div></div></div></div></template>
